import { createSlice, configureStore, PayloadAction } from '@reduxjs/toolkit';

export type Todo = { id: number; title: string; done: boolean };

const todosSlice = createSlice({
  name: 'todos',
  initialState: [] as Todo[],
  reducers: {
    add: (state, action: PayloadAction<Todo>) => {
      state.push(action.payload);
    },
    toggle: (state, action: PayloadAction<number>) => {
      const t = state.find((x) => x.id === action.payload);
      if (t) t.done = !t.done;
    },
  },
});

export const { add, toggle } = todosSlice.actions;

export const store = configureStore({
  reducer: { todos: todosSlice.reducer },
});

export type RootState = ReturnType<typeof store.getState>;
export type AppDispatch = typeof store.dispatch;

import { useDispatch, useSelector } from 'react-redux';
import { add, AppDispatch, RootState, toggle } from './store';

export function TodoList() {
  const todos = useSelector((s: RootState) => s.todos);
  const dispatch = useDispatch<AppDispatch>();
  return (
    <>
      <button onClick={() => dispatch(add({ id: Date.now(), title: 'new', done: false }))}>add</button>
      <ul>
        {todos.map((t) => (
          <li key={t.id}>
            <button onClick={() => dispatch(toggle(t.id))}>{t.done ? 'x' : 'o'}</button>
            <span>{t.title}</span>
          </li>
        ))}
      </ul>
    </>
  );
}
